function opsCopyCleaningImage() {
  const el = document.getElementById('ops-cleaning-shot');
  if (!el) { if (typeof toast === 'function') toast('Cleaning table not on screen', 'err'); return; }
  const run = async function () {
    if (typeof html2canvas === 'undefined') {
      if (typeof toast === 'function') toast('Loading html2canvas…', 'warn');
      await new Promise(function (res, rej) {
        const s = document.createElement('script');
        s.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
        s.onload = res; s.onerror = rej; document.head.appendChild(s);
      });
    }
    if (typeof toast === 'function') toast('Capturing cleaning table…');
    // Clone + flatten inputs/selects/textareas to plain text nodes so html2canvas
    // does not distort centered cleaner names.
    const clone = el.cloneNode(true);
    clone.querySelectorAll('[data-cleaners-cell]').forEach(function (td) {
      const names = (td.getAttribute('data-cleaners-names') || '').trim();
      td.innerHTML = '<div style="font-size:15px;font-weight:700;color:#111827;text-align:center;line-height:1.35;padding:10px 8px;border:1.5px solid #111827;border-radius:8px;background:#FFFBEB;min-height:28px;display:flex;align-items:center;justify-content:center;white-space:pre-wrap;word-break:break-word;">' +
        (names ? names.replace(/ · /g, '\n') : '—') + '</div>';
    });
    // Crew sheet: drop "+ γραμμή / + οδηγός" chrome and empty staff rows before flattening.
    clone.querySelectorAll('button').forEach(function (btn) {
      const t = String(btn.textContent || '');
      if (/^\+\s/.test(t) || /γραμμή|οδηγός|Καθαρίστριες|Screenshot|Αντιγραφή|Κατάσταση|καθαρίστρια/i.test(t)) btn.remove();
    });
    clone.querySelectorAll('select, input[list="ops-cleaners-datalist"], input[list="ops-drivers-datalist"]').forEach(function (node) {
      const v = (node.tagName === 'SELECT')
        ? (node.options[node.selectedIndex] ? node.options[node.selectedIndex].text : node.value)
        : node.value;
      const empty = !String(v || '').trim() || v === '—';
      if (empty) {
        const row = node.closest('div[style*="display:flex"]') || node.parentElement;
        if (row && row.parentElement) row.remove();
      }
    });
    clone.querySelectorAll('input, textarea, select, button').forEach(function (node) {
      if (node.tagName === 'BUTTON') { node.remove(); return; }
      const v = (node.tagName === 'SELECT')
        ? (node.options[node.selectedIndex] ? node.options[node.selectedIndex].text : node.value)
        : node.value;
      const div = document.createElement('div');
      const isCleaner = node.getAttribute('list') === 'ops-cleaners-datalist' || node.getAttribute('list') === 'ops-drivers-datalist';
      div.textContent = v || '—';
      div.style.cssText = isCleaner
        ? 'font-size:15px;font-weight:700;color:#111827;text-align:center;line-height:1.25;padding:8px 6px;border:1.5px solid #111827;border-radius:8px;background:#FFFBEB;min-height:28px;display:flex;align-items:center;justify-content:center;'
        : 'font-size:12px;font-weight:600;color:#111827;line-height:1.35;padding:4px 2px;white-space:pre-wrap;word-break:break-word;';
      node.parentNode.replaceChild(div, node);
    });
    clone.style.position = 'fixed';
    clone.style.left = '-10000px';
    clone.style.top = '0';
    clone.style.width = el.offsetWidth + 'px';
    clone.style.zIndex = '-1';
    document.body.appendChild(clone);
    const canvas = await html2canvas(clone, {
      scale: 2, backgroundColor: '#ffffff', useCORS: true, logging: false
    });
    clone.remove();
    const blob = await new Promise(function (res) { canvas.toBlob(res, 'image/png'); });
    if (!blob) throw new Error('Could not build PNG');
    if (navigator.clipboard && window.ClipboardItem) {
      await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
      if (typeof toast === 'function') toast('Cleaning table copied — paste into chat', 'ok');
    } else {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'programma-katharismou-' + (_opsDate || 'today') + '.png';
      document.body.appendChild(a); a.click(); a.remove();
      if (typeof toast === 'function') toast('Downloaded PNG (clipboard not available)', 'ok');
    }
  };
  run().catch(function (e) {
    if (typeof toast === 'function') toast('Screenshot failed: ' + (e && e.message ? e.message : e), 'err');
  });
}

